#!/usr/bin/env node
/**
 * Tests for the /worklog PowerShell scripts: the engine's pause rules (worklog.ps1) and the only
 * writer of hours (worklog-push.ps1). Zero dependencies — `node:test` on Node 18+, plus pwsh 7.
 *
 *   node --test "tools/*.test.mjs"
 *
 * The engine runs on fabricated transcripts in a temp projects root, dated today so the file filter
 * keeps them. The push runs against an `az` shim first on PATH that keeps CompletedWork in a JSON
 * file and logs every call: no test ever reaches Azure DevOps.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const SKILL = join(dirname(fileURLToPath(import.meta.url)), '..', 'skills', 'worklog');
const created = [];
process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});
const tmp = () => { const d = mkdtempSync(join(tmpdir(), 'wls-')); created.push(d); return d; };

const hasPwsh = spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' }).status === 0;
const skip = hasPwsh ? false : 'pwsh 7 not on PATH';
const skipWin = !hasPwsh ? 'pwsh 7 not on PATH' : (process.platform === 'win32' ? false : 'az shim is a .cmd');

function pwsh(script, args, env = process.env) {
  const r = spawnSync('pwsh', ['-NoProfile', '-File', join(SKILL, script), ...args], { encoding: 'utf8', env });
  return { code: r.status, out: `${r.stdout}${r.stderr}` };
}

// ── engine: which gaps are work ─────────────────────────────────────────────────────────────────

const pad = (n) => String(n).padStart(2, '0');
const now = new Date();
const TODAY = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
/** Today at local 10:00 plus `min` minutes, as the transcripts store it (UTC ISO). */
const at = (min) => new Date(now.getFullYear(), now.getMonth(), now.getDate(), 10, min, 0).toISOString();

const ev = (min, type, content, { session = 's1', branch = 'feature/a' } = {}) => ({
  type, timestamp: at(min), sessionId: session, cwd: 'C:\\work\\api', gitBranch: branch,
  message: { role: type, content },
});
const prompt = (min, opts) => ev(min, 'user', 'fai la cosa', opts);
const reply = (min, opts) => ev(min, 'assistant', [{ type: 'text', text: 'fatto' }], opts);
const toolUse = (min, id, input = {}) => ev(min, 'assistant', [{ type: 'tool_use', id, name: 'Bash', input }]);
const toolResult = (min, id) => ev(min, 'user', [{ type: 'tool_result', tool_use_id: id, content: 'ok' }]);

/** Runs the engine on `main` (and optional subagent events) and returns today's active minutes. */
function activeMinutes(main, sub = []) {
  const root = tmp();
  const proj = join(root, 'C--work-api');
  mkdirSync(join(proj, 's1', 'subagents'), { recursive: true });
  writeFileSync(join(proj, 's1.jsonl'), main.map((e) => JSON.stringify(e)).join('\n'));
  if (sub.length) writeFileSync(join(proj, 's1', 'subagents', 'agent-x.jsonl'), sub.map((e) => JSON.stringify({ ...e, isSidechain: true })).join('\n'));
  const r = pwsh('worklog.ps1', ['-From', TODAY, '-ProjectsRoot', root, '-OutDir', join(root, 'out')]);
  assert.equal(r.code, 0, r.out);
  const m = r.out.match(/Tempo attivo totale: (?:(\d+)h )?(\d+)m/);
  assert.ok(m, r.out);
  return Number(m[1] || 0) * 60 + Number(m[2]);
}

test('a 30-min gap on the same topic is continuity, not a pause', { skip }, () => {
  assert.equal(activeMinutes([prompt(0), reply(1), prompt(31), reply(32)]), 32);
});

test('a 50-min gap with nothing in flight is a pause', { skip }, () => {
  assert.equal(activeMinutes([prompt(0), reply(1), prompt(51), reply(52)]), 2);
});

test('a 30-min topic switch with nothing in flight is a pause', { skip }, () => {
  const b = { session: 's2', branch: 'feature/b' };
  assert.equal(activeMinutes([prompt(0), reply(1), prompt(31, b), reply(32, b)]), 2);
});

test('a 60-min foreground tool call (a build, a test run) counts', { skip }, () => {
  assert.equal(activeMinutes([prompt(0), toolUse(1, 't1'), toolResult(61, 't1'), reply(62)]), 62);
});

test('a subagent working through a 60-min gap counts', { skip }, () => {
  const sub = Array.from({ length: 13 }, (_, i) => reply(2 + i * 5));   // 10:02 … 11:02
  assert.equal(activeMinutes([prompt(0), reply(1), prompt(62), reply(63)], sub), 63);
});

test('a background dev server does not stretch a 60-min gap', { skip }, () => {
  const main = [
    prompt(0), toolUse(1, 'bg1', { run_in_background: true }), toolResult(1, 'bg1'),
    prompt(61), reply(62),
    { type: 'queue-operation', operation: 'enqueue', timestamp: at(90), sessionId: 's1',
      content: '<task-notification><tool-use-id>bg1</tool-use-id></task-notification>' },
  ];
  assert.equal(activeMinutes(main), 2);
});

// ── push: cumulative, idempotent, audited ───────────────────────────────────────────────────────

/** A sandbox: az shim on PATH, CompletedWork state, an empty worklog folder. */
function sandbox(state = { 101: 2 }) {
  const dir = tmp();
  const bin = join(dir, 'bin');
  mkdirSync(bin);
  writeFileSync(join(dir, 'state.json'), JSON.stringify(state));
  writeFileSync(join(bin, 'az-shim.cjs'), `
const fs = require('fs'); const path = require('path');
const dir = path.join(__dirname, '..'); const a = process.argv.slice(2);
fs.appendFileSync(path.join(dir, 'calls.log'), a.join(' ') + '\\n');
const st = JSON.parse(fs.readFileSync(path.join(dir, 'state.json'), 'utf8'));
const id = a[a.indexOf('--id') + 1];
if (!(id in st)) { process.stderr.write('ERROR: work item ' + id + ' not found'); process.exit(1); }
if (a[2] === 'update') {
  const f = a.slice(a.indexOf('--fields') + 1).find((x) => x.startsWith('Microsoft.VSTS.Scheduling.CompletedWork='));
  if (f) st[id] = Number(f.split('=')[1]);
  fs.writeFileSync(path.join(dir, 'state.json'), JSON.stringify(st));
}
process.stdout.write(JSON.stringify({ id: Number(id), fields: { 'Microsoft.VSTS.Scheduling.CompletedWork': st[id] } }));
`);
  writeFileSync(join(bin, 'az.cmd'), '@node "%~dp0az-shim.cjs" %*\r\n');
  const pathKey = Object.keys(process.env).find((k) => k.toLowerCase() === 'path') || 'PATH';
  const env = { ...process.env, [pathKey]: `${bin};${process.env[pathKey]}`, AZ_IDENTITY: '' };
  const push = (rows, ...flags) => {
    const file = join(dir, 'rows.json');
    writeFileSync(file, JSON.stringify(rows));
    return pwsh('worklog-push.ps1', ['-Rows', file, '-OutDir', join(dir, 'wl'), '-ConfigPath', join(dir, 'none.json'), ...flags], env);
  };
  const read = (name) => JSON.parse(readFileSync(join(dir, name), 'utf8'));
  const calls = () => (existsSync(join(dir, 'calls.log')) ? readFileSync(join(dir, 'calls.log'), 'utf8').trim().split('\n') : []);
  return { dir, push, read, calls };
}

const row = (extra = {}) => ({ date: '2026-10-20', org: 'contoso', project: 'P', itemId: 101, hours: 1.5, topic: 'fix cache', ...extra });

test('push adds the delta to CompletedWork and records the period total in the audit', { skip: skipWin }, () => {
  const sb = sandbox();
  const r = sb.push([row()]);
  assert.equal(r.code, 0, r.out);
  assert.equal(sb.read('state.json')[101], 3.5);
  const [e] = sb.read('wl/pushed.json');
  assert.equal(e.hoursLogged, 1.5);
  assert.equal(e.periodFrom, '2026-10-20');
  assert.equal(e.mcp, 'cli');
});

test('push re-run of the same row writes nothing; a higher total adds only the difference', { skip: skipWin }, () => {
  const sb = sandbox();
  sb.push([row()]);
  const before = sb.calls().length;
  sb.push([row()]);
  assert.equal(sb.calls().slice(before).filter((c) => c.includes(' update ')).length, 0);
  sb.push([row({ hours: 2 })]);
  assert.equal(sb.read('state.json')[101], 4);
  assert.equal(sb.read('wl/pushed.json').length, 1);
});

test('push re-run with a minimal row keeps the parent, the created flag and the links', { skip: skipWin }, () => {
  const sb = sandbox();
  sb.push([row({ created: true, parentId: 50, prs: [1] })]);
  sb.push([row()]);
  const [e] = sb.read('wl/pushed.json');
  assert.equal(e.created, true);
  assert.equal(e.parentId, 50);
  assert.deepEqual(e.prs, [1]);
});

test('push honours an explicit delta 0 (hours already logged by hand) and still closes the day', { skip: skipWin }, () => {
  const sb = sandbox();
  sb.push([row({ hours: 3, delta: 0 })]);
  assert.equal(sb.read('state.json')[101], 2);
  assert.equal(sb.read('wl/pushed.json')[0].hoursLogged, 3);
});

test('push close and target rows touch only the audit and targets.json', { skip: skipWin }, () => {
  const sb = sandbox();
  const r = sb.push([
    { date: '2026-10-13', itemId: null, hours: 0, topic: 'nulla-da-registrare' },
    { date: '2026-10-13', targetHours: 0, note: 'evento' },
  ]);
  assert.equal(r.code, 0, r.out);
  assert.equal(sb.calls().length, 0);
  assert.equal(sb.read('wl/pushed.json')[0].topic, 'nulla-da-registrare');
  assert.deepEqual(sb.read('wl/targets.json').days['2026-10-13'], { hours: 0, note: 'evento' });
});

test('push -DryRun calls nothing and writes nothing', { skip: skipWin }, () => {
  const sb = sandbox();
  const r = sb.push([row(), { date: '2026-10-13', targetHours: 0 }], '-DryRun');
  assert.equal(r.code, 0, r.out);
  assert.equal(sb.calls().length, 0);
  assert.ok(!existsSync(join(sb.dir, 'wl', 'pushed.json')));
  assert.ok(!existsSync(join(sb.dir, 'wl', 'targets.json')));
});

test('push: a failing item exits 1 and leaves its audit entry unwritten, the others go through', { skip: skipWin }, () => {
  const sb = sandbox();
  const r = sb.push([row({ itemId: 999 }), row()]);
  assert.equal(r.code, 1);
  assert.match(r.out, /ERRORE/);
  const audit = sb.read('wl/pushed.json');
  assert.deepEqual(audit.map((e) => e.itemId), [101]);
});
